const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "../../src/simulations/pre-made");
const slugs = fs
  .readdirSync(root)
  .filter((slug) => fs.existsSync(path.join(root, slug, "recipe.json")))
  .sort();
const source =
  "// Generated by scripts/recipes/generate-registry.cjs. Do not edit.\n" +
  slugs
    .map(
      (slug, index) =>
        `import recipe${index} from "../../pre-made/${slug}/recipe.json";`,
    )
    .join("\n") +
  "\nexport const premadeSources = {\n" +
  slugs.map((slug, index) => `  "${slug}": recipe${index},`).join("\n") +
  "\n} as const;\n";
const target = path.resolve(
  __dirname,
  "../../src/simulations/registry/recipes/premade.generated.ts",
);
if (process.argv.includes("--check")) {
  if (fs.readFileSync(target, "utf8") !== source)
    throw new Error("Premade registry is stale");
} else fs.writeFileSync(target, source);
